proguardAdditions.insert:

-keep class com.taptap.sdk.rep.** { *; }
-keep interface com.taptap.sdk.rep.** { *; }
-keepclassmembers class com.taptap.sdk.rep.enginebridge.** { *; }
-keepclasseswithmembernames class * { native <methods>; }
-keep class com.taptap.sdk.kit.internal.enginebridge.EngineBridgeCallbackProxy { *; }
-keep interface com.taptap.sdk.kit.internal.enginebridge.EngineBridgeCallback { *; }

gameActivityClassAdditions.insert:

private BridgeRepServiceImpl mRepService;

private BridgeRepServiceImpl getRepService() {
    if (mRepService == null) { mRepService = new BridgeRepServiceImpl(); }
    return mRepService;
}

public void routeToTapRep(String requestJson, EngineBridgeCallback callback) {
    try {
        org.json.JSONObject req = new org.json.JSONObject(requestJson);
        String method  = req.getString("method");
        String argsStr = req.optString("args", "");
        switch (method) {
            case "open": {
                String openUrl = new org.json.JSONObject(argsStr).optString("openUrl", "");
                getRepService().open(openUrl, callback);
                break;
            }
            default:
                android.util.Log.w("TapSDK_UE", "TapRep: unknown method: " + method);
                callback.onResult(
                    "{\"code\":-1,\"message\":\"unknown TapRep method\"}");
        }
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapRep route error: " + e.getMessage(), e);
        callback.onResult(
            "{\"code\":-1,\"message\":\"TapRep route error: "
                + String.valueOf(e.getMessage()).replace("\"", "'")
                + "\"}");
    }
}
